static inline bool contains(const std::uint32_t* data,std::size_t n,std::uint32_t x){
    return std::binary_search(data,data+n,x);
}
static inline bool isBodyKey(unsigned palette,unsigned tile){
    if(palette>=32u || tile>0x07FFFFFFu)return false;
    const std::uint32_t key=(static_cast<std::uint32_t>(tile)<<5)|palette;
    return contains(kKnownBodyKeys,sizeof(kKnownBodyKeys)/sizeof(kKnownBodyKeys[0]),key);
}
static inline bool isBodyTile(unsigned tile){
    return contains(kBodyTiles,sizeof(kBodyTiles)/sizeof(kBodyTiles[0]),static_cast<std::uint32_t>(tile));
}
static inline bool isMixedKey(unsigned palette,unsigned tile){
    if(palette>=32u || tile>0x07FFFFFFu)return false;
    const std::uint32_t key=(static_cast<std::uint32_t>(tile)<<5)|palette;
    return contains(kMixedBodyFxKeys,sizeof(kMixedBodyFxKeys)/sizeof(kMixedBodyFxKeys[0]),key);
}
static inline Kind classify(unsigned priority,unsigned palette,unsigned tile,
                            bool confirmedPriorFx,bool bodyConflict){
    // Caller restricts this policy to priority 6 during active combat.
    if(priority!=6u)return GrayscaleBody;
    if(bodyConflict)return GrayscaleBody;
    // A previously confirmed isolated effect wins unless it also has
    // documented body identity with this exact palette.
    if(confirmedPriorFx && !isBodyKey(palette,tile))return FullEffect;
    if(isBodyKey(palette,tile))
        return isMixedKey(palette,tile)?MixedPenEffect:GrayscaleBody;
    if(isBodyTile(tile)){
        // P2 high palettes 16/17 were repeatedly observed on whole
        // fighter bodies as hit/lighting flashes, not safe FX evidence.
        if(palette==16u || palette==17u)return GrayscaleBody;
        return MixedPenEffect; // Reused body art: admit only luminous pens
    }
    return FullEffect; // Subtractive default: unknown isolated art is colored
}
